INSERT INTO collection_pages VALUES('13314312014f941b000e3ed7bdab8c5d5136c23adf09e3f9161049a5b6fe3568','04df2f47b335e3c2be36fe09e1fe07a9817d044e4d279bde8cb1123c91e9daec','{"hasNext":false,"items":[{"author":{"account":null,"email":"sandeep.prasad@phenom.com","name":"Sandeep Prasad"},"authoredDate":"2026-05-22T07:45:22Z","committedDate":"2026-05-22T07:45:22Z","committer":{"account":null,"email":"sandeep.prasad@phenom.com","name":"Sandeep Prasad"},"observedAt":"2026-10-08T23:07:50.104Z","repositoryId":1246411314,"sha":"be21b51a3d049dbee3d6acbedf8228085b77e1fa"},{"author":{"account":null,"email":"sandeep.prasad@phenom.com","name":"Sandeep Prasad"},"authoredDate":"2026-05-22T07:09:32Z","committedDate":"2026-05-22T07:09:32Z","committer":{"account":null,"email":"sandeep.prasad@phenom.com","name":"Sandeep Prasad"},"observedAt":"2026-10-08T23:07:50.104Z","repositoryId":1246411314,"sha":"e5d01266b21fd4ee9bf2d1a6783b9fe27db18a14"}],"observedAt":"2026-10-08T23:07:50.104Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/commits/be21b51a3d049dbee3d6acbedf8228085b77e1fa/comments","commit":{"author":{"date":"2026-05-22T07:45:22Z","email":"sandeep.prasad@phenom.com","name":"Sandeep Prasad"},"comment_count":0,"committer":{"date":"2026-05-22T07:45:22Z","email":"sandeep.prasad@phenom.com","name":"Sandeep Prasad"},"message":"chore(resume): add Sandeep_Prasad_Resume.pdf + .docx source\n\nReplaces the placeholder README in public/resume/. The PDF is exported\nfrom the source DOCX and serves at /resume/Sandeep_Prasad_Resume.pdf,\nwhich is already what the Download Resume buttons point at — no code\nchange required.\n\n- Sandeep_Prasad_Resume.pdf (primary; what recruiters download)\n- Sandeep_Prasad_Resume.docx (kept as the editable source)\n\nCo-authored-by: Cursor <cursoragent@cursor.com>","tree":{"sha":"0be4f0f0e0e6a6f5510ff1517a4b795171c31c62","url":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/git/trees/0be4f0f0e0e6a6f5510ff1517a4b795171c31c62"},"url":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/git/commits/be21b51a3d049dbee3d6acbedf8228085b77e1fa","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/ahexdev1/sandeep_portfolio/commit/be21b51a3d049dbee3d6acbedf8228085b77e1fa","node_id":"C_kwDOSkq6MtoAKGJlMjFiNTFhM2QwNDlkYmVlM2Q2YWNiZWRmODIyODA4NWI3N2UxZmE","parents":[{"html_url":"https://github.com/ahexdev1/sandeep_portfolio/commit/e5d01266b21fd4ee9bf2d1a6783b9fe27db18a14","sha":"e5d01266b21fd4ee9bf2d1a6783b9fe27db18a14","url":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/commits/e5d01266b21fd4ee9bf2d1a6783b9fe27db18a14"}],"sha":"be21b51a3d049dbee3d6acbedf8228085b77e1fa","url":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/commits/be21b51a3d049dbee3d6acbedf8228085b77e1fa"},{"author":null,"comments_url":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/commits/e5d01266b21fd4ee9bf2d1a6783b9fe27db18a14/comments","commit":{"author":{"date":"2026-05-22T07:09:32Z","email":"sandeep.prasad@phenom.com","name":"Sandeep Prasad"},"comment_count":0,"committer":{"date":"2026-05-22T07:09:32Z","email":"sandeep.prasad@phenom.com","name":"Sandeep Prasad"},"message":"feat: initial portfolio site for Sandeep Prasad\n\nPremium recruiter-focused portfolio for a Senior Frontend Architect.\n\n- React 18 + TypeScript + Vite 5\n- Tailwind CSS 3 with CSS-variable theming (dark + light)\n- React Router 6 with lazy-loaded routes: /, /case/:slug, /resume\n- Framer Motion scroll reveals (respects prefers-reduced-motion)\n- Sections: Hero, Trust, About, Expertise (bento), Case Studies,\n  Experience, Tech Stack, Achievements, Contact, Footer\n- Per-project deep-dive pages (Context, Challenges, Decisions,\n  Impact, Learnings, Team)\n- Print-friendly /resume page with dedicated @media print styles\n- Resume PDF download wired into nav, hero, case studies and contact\n- Theme toggle with localStorage persistence and anti-FOUC inline script\n- Vercel Analytics integration\n- SEO: JSON-LD Person schema, OpenGraph, Twitter Cards, custom OG image\n- Accessibility: skip-to-content, focus rings, semantic HTML\n- vercel.json with SPA rewrites and caching headers\n- Netlify _redirects fallback included\n\nCo-authored-by: Cursor <cursoragent@cursor.com>","tree":{"sha":"01ffee622beb5cf6ddd923e478784097d2d7e90c","url":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/git/trees/01ffee622beb5cf6ddd923e478784097d2d7e90c"},"url":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/git/commits/e5d01266b21fd4ee9bf2d1a6783b9fe27db18a14","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/ahexdev1/sandeep_portfolio/commit/e5d01266b21fd4ee9bf2d1a6783b9fe27db18a14","node_id":"C_kwDOSkq6MtoAKGU1ZDAxMjY2YjIxZmQ0ZWU5YmYyZDFhNjc4M2I5ZmUyN2RiMThhMTQ","parents":[],"sha":"e5d01266b21fd4ee9bf2d1a6783b9fe27db18a14","url":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/commits/e5d01266b21fd4ee9bf2d1a6783b9fe27db18a14"}],"requestUrl":"https://api.github.com/repos/ahexdev1/sandeep_portfolio/commits?per_page=100&page=1&sha=be21b51a3d049dbee3d6acbedf8228085b77e1fa&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A00%3A10.869Z"}');
